cd /home/eslam/Downloads/TTFolder/quickflow-claude-loops && python3 - <<'EOF'
import xml.etree.ElementTree as ET
r=ET.parse('loops/testing/runs/001-quickflow/backend-dev/phase-02/attempt-1/unit/coverage/jacoco.xml').getroot()
for p in r.findall('package'):
    for c in p.findall('counter'):
        if c.get('type')=='LINE': print(p.get('name'),c.attrib)
